import { browser } from 'wxt/browser';
import { resolveWllamaAssetUrls } from './assets';
import {
  loadWllamaModule,
  type Wllama,
  type WllamaConfig,
  type WllamaModuleLoader,
} from './module';

export interface CreateWllamaOptions extends WllamaConfig {
  getUrl?: (path: string) => string;
  loadModule?: WllamaModuleLoader;
}

// WXT types getURL against the files present when `wxt prepare` runs; the vendor assets are
// generated by `pnpm build:wllama` afterwards.
function runtimeUrl(path: string): string {
  return (browser.runtime.getURL as (path: string) => string)(path);
}

export async function createWllama(options: CreateWllamaOptions = {}): Promise<Wllama> {
  const { getUrl = runtimeUrl, loadModule = loadWllamaModule, ...config } = options;

  const urls = resolveWllamaAssetUrls(getUrl);
  const { Wllama: WllamaConstructor } = await loadModule(urls.library);

  return new WllamaConstructor(
    {
      default: urls.wasm,
      'wllama.worker.js': urls.worker,
      'wllama.module.js': urls.module,
      'wllama.pthread.js': urls.pthread,
      'wllama.compat.js': urls.compatModule,
      'wllama.compat.pthread.js': urls.compatPthread,
      'wllama.compat.wasm': urls.compatWasm,
    },
    config,
  );
}
